#!/usr/bin/env python3
import argparse,hashlib,json,pathlib,platform,statistics,subprocess,tempfile,time
from bench_startup import Mock,prepare,run_once
from bench_protocol_startup import measure
CAPTURES=[]
Popen=subprocess.Popen
class CapturingPopen(Popen):
 def communicate(self,*args,**kwargs):
  out,err=super().communicate(*args,**kwargs)
  if err and b'PROFILE ' in err:
   lines=err.splitlines()
   trace=[json.loads(line.removeprefix(b'PROFILE ')) for line in lines if line.startswith(b'PROFILE ')]
   clock=[json.loads(line.removeprefix(b'FINX_STARTUP_CLOCK ')) for line in lines if line.startswith(b'FINX_STARTUP_CLOCK ')]
   if len(trace)!=1 or len(clock)!=1: raise RuntimeError('expected exactly one trace and native clock')
   CAPTURES.append({'trace':trace[0],'clock':clock[0]})
  return out,err
subprocess.Popen=CapturingPopen
p=argparse.ArgumentParser();p.add_argument('--finx',required=True);p.add_argument('--launcher',required=True);p.add_argument('--runs',type=int,default=100);p.add_argument('--warmup',type=int,default=10);p.add_argument('--json',required=True)
a=p.parse_args(); binary=str(pathlib.Path(a.finx).resolve());launcher=str(pathlib.Path(a.launcher).resolve())
