with tempfile.TemporaryDirectory(prefix='fxs-',dir='/tmp') as tmp:
 root=pathlib.Path(tmp)
 cases=[(mode,*prepare(root/mode,mock.port,config='model="mock/bench"\npermission_mode="manual"\n')) for mode in samples]
 for i in range(a.runs+a.warmup):
  shift=i%len(cases)
  for mode,env,cwd in cases[shift:]+cases[:shift]:
   before=len(mock.arrivals); captured=len(CAPTURES)
   if mode=='cli':
    row=run_once([binary,'exec','-m','mock/bench','--permission-mode','manual','hello'],env,cwd,mock,30,launcher)
   else:
    row=measure(binary,mode,env,cwd,mock,30,launcher,root/'s.sock')
   if len(CAPTURES)!=captured+1:raise RuntimeError('missing trace')
   entry=CAPTURES[-1]; marks=dict(entry['trace']);start=entry['clock']['start_ns'];arrival=mock.arrivals[before]
   if not start<=marks['main']<=marks['send_request']<=arrival<=marks['response']:raise RuntimeError('invalid clock boundaries')
   entry.update(metrics=row,arrival_ns=arrival)
